const fmt=n=>Math.floor(n||0).toLocaleString('vi-VN');
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const now=()=>Date.now();
const hour=3600000;
let selectedAction='harvest', selectedCrop='carrot', soundOn=false, tickTimer=null;
const emptyMaterials=()=>Object.fromEntries(Object.keys(MATERIAL_CONFIG).map(k=>[k,0]));
const emptyCrops=()=>Object.fromEntries(CROP_CONFIG.map(c=>[c.id,{normal:0,fresh:0,premium:0}]));
const defaultFriendships=()=>Object.fromEntries(ORDER_CUSTOMERS.map(c=>[c.id,0]));
function newPlot(i){return {id:i,cropId:null,plantedAt:0,wateredAt:0,diseaseAt:0,deadAt:0,deadReason:'',treatedAt:0}}
function defaultState(){return {version:3,createdAt:now(),lastSeen:now(),gold:INITIAL_GOLD,diamonds:0,exp:0,level:1,playerName:'Chủ vườn',farmName:'Nông Trại Nhỏ',avatar:'👨‍🌾',warehouse:{capacity:INITIAL_WAREHOUSE,crops:emptyCrops(),materials:emptyMaterials()},plots:Array.from({length:MAX_PLOTS},(_,i)=>newPlot(i)),unlockedPlotCount:INITIAL_PLOTS,speedLevel:0,orders:Array.from({length:ORDER_SLOT_COUNT},()=>null),orderCooldown:Array.from({length:ORDER_SLOT_COUNT},()=>0),friendships:defaultFriendships(),season:{chapter:1,name:'Mùa Khởi Hành',points:0,stars:0,completed:0,goal:SEASON_GOAL_BASE,activePerks:[],choiceQueue:[],history:[],nextStoryAt:3,metaBoost:0},house:{built:{villa_1:true},styles:{roof:'red',fence:'wood',path:'stone'}},tutorial:{step:0,seenDiamond:false},stats:{harvested:0,orders:0,sold:0,cropsPlanted:0,diamondsMade:0},achievements:{},lastWeatherKey:'',lastSavedAt:0};}
let state=defaultState();
let currentProfileId='';
let gameStarted=false;
function activeSaveKey(){return currentProfileId?`${SAVE_KEY_PREFIX}${currentProfileId}`:SAVE_KEY}
function getProfilesMeta(){try{return JSON.parse(localStorage.getItem(PROFILE_META_KEY)||'{}')}catch{return {}}}
function setProfilesMeta(meta){localStorage.setItem(PROFILE_META_KEY,JSON.stringify(meta))}
function updateProfileMetaFromState(){if(!currentProfileId)return;const meta=getProfilesMeta();meta[currentProfileId]={playerName:state.playerName||'Chủ vườn',farmName:state.farmName||'Nông Trại Nhỏ',avatar:state.avatar||'👨‍🌾',level:state.level||1,lastPlayed:now(),gold:state.gold||0};setProfilesMeta(meta)}
function save(){state.lastSeen=now();state.lastSavedAt=state.lastSeen;localStorage.setItem(activeSaveKey(),JSON.stringify(state));updateProfileMetaFromState()}
function load(){const raw=localStorage.getItem(activeSaveKey());if(raw){try{const v=JSON.parse(raw);state=migrateV2(v);return}catch(e){console.warn(e)}}state=defaultState();if(currentProfileId==='1')migrateLegacy()}
function migrateV2(v){const base=defaultState();const s={...base,...v,warehouse:{...base.warehouse,...(v.warehouse||{})},house:{...base.house,...(v.house||{}),styles:{...base.house.styles,...(v.house?.styles||{})}},stats:{...base.stats,...(v.stats||{})},tutorial:{...base.tutorial,...(v.tutorial||{})}};s.warehouse.crops={...emptyCrops(),...(v.warehouse?.crops||{})};s.warehouse.materials={...emptyMaterials(),...(v.warehouse?.materials||{})};s.friendships={...defaultFriendships(),...(v.friendships||{})};s.season={...defaultState().season,...(v.season||{})};s.orders=Array.from({length:ORDER_SLOT_COUNT},(_,i)=>(v.orders?.[i]??null));s.orderCooldown=Array.from({length:ORDER_SLOT_COUNT},(_,i)=>(v.orderCooldown?.[i]??0));s.plots=Array.from({length:MAX_PLOTS},(_,i)=>({...newPlot(i),...(v.plots?.[i]||{})}));s.version=3;s.playerName=s.playerName||'Chủ vườn';s.farmName=s.farmName||'Nông Trại Nhỏ';s.avatar=s.avatar||'👨‍🌾';if(!s.house.built||typeof s.house.built!=='object')s.house.built={};s.house.built.villa_1=true;return s}
function migrateLegacy(){const raw=localStorage.getItem(LEGACY_SAVE_KEY)||localStorage.getItem(SAVE_KEY);if(!raw)return;try{const old=JSON.parse(raw);state=migrateV2(old);if(!old.warehouse){state.gold=Math.max(INITIAL_GOLD,Math.min(Number(old.gold)||INITIAL_GOLD,25000));state.unlockedPlotCount=clamp(old.unlockedPlotCount||INITIAL_PLOTS,INITIAL_PLOTS,MAX_PLOTS);const map={carrot:'carrot',potato:'potato',corn:'corn',strawberry:'strawberry',watermelon:'watermelon',pumpkin:'pumpkin',diamond:'blueberry'};(old.plots||[]).slice(0,MAX_PLOTS).forEach((p,i)=>{if(p?.cropType&&map[p.cropType])state.plots[i]={...newPlot(i),cropId:map[p.cropType],plantedAt:p.startTime||now(),wateredAt:p.startTime||now()}})}if(!state.playerName||state.playerName==='Chủ vườn')state.playerName='Chủ vườn';if(!state.farmName||state.farmName==='Nông Trại Nhỏ')state.farmName='Nông Trại Gia Đình';save()}catch(e){console.warn('Không migration được Farm cũ',e)}}
function ensureProfileBoot(){let meta=getProfilesMeta();let current=localStorage.getItem(CURRENT_PROFILE_KEY)||'';if(!Object.keys(meta).length&&(localStorage.getItem(SAVE_KEY)||localStorage.getItem(LEGACY_SAVE_KEY))){current='1';currentProfileId='1';state=defaultState();load();updateProfileMetaFromState();save();meta=getProfilesMeta();localStorage.setItem(CURRENT_PROFILE_KEY,'1')}if(current)currentProfileId=current}
function switchProfile(slot){currentProfileId=String(slot);localStorage.setItem(CURRENT_PROFILE_KEY,currentProfileId);gameStarted=true;startGame();renderProfileDialog();$('#profileDialog').close();save()}
function createProfile(slot){const avatars=['👨‍🌾','👩‍🌾','🧒','👧','🧑'];const playerName=(prompt('Tên người chơi:', slot==='1'?'Sunny':'Chủ vườn')||'').trim()||'Chủ vườn';const farmName=(prompt('Tên nông trại:', `Vườn ${playerName}`)||'').trim()||`Vườn ${playerName}`;currentProfileId=String(slot);state=defaultState();state.playerName=playerName;state.farmName=farmName;state.avatar=avatars[(Number(slot)-1)%avatars.length];localStorage.setItem(CURRENT_PROFILE_KEY,currentProfileId);save();gameStarted=true;startGame();renderProfileDialog();$('#profileDialog').close()}
function renderProfileDialog(){const host=$('#profileDialogBody');if(!host)return;const meta=getProfilesMeta();host.innerHTML=Array.from({length:PROFILE_COUNT},(_,i)=>{const slot=String(i+1),p=meta[slot];return `<div class="profile-slot ${currentProfileId===slot?'active':''}"><div class="profile-slot-main"><div class="profile-avatar">${p?.avatar||'➕'}</div><div><div class="profile-title">Slot ${slot} ${p?`· ${p.farmName}`:'· Trống'}</div><div class="profile-sub">${p?`${p.playerName} · Cấp ${p.level||1} · ${fmt(p.gold||0)}G`:'Tạo nông trại mới tại slot này'}</div></div></div><div class="row-actions">${p?`<button class="mini-btn" data-slot-open="${slot}">Vào game</button>`:`<button class="primary-btn" data-slot-create="${slot}">Tạo mới</button>`}</div></div>`}).join('');host.querySelectorAll('[data-slot-open]').forEach(b=>b.onclick=()=>switchProfile(b.dataset.slotOpen));host.querySelectorAll('[data-slot-create]').forEach(b=>b.onclick=()=>createProfile(b.dataset.slotCreate))}
function openProfileDialog(force=false){renderProfileDialog();const dlg=$('#profileDialog');if(force||!gameStarted){if(!dlg.open)dlg.showModal()}else if(!dlg.open)dlg.showModal()}
function friendshipOf(id){return state.friendships?.[id]||0}
function addFriendship(id,n){state.friendships[id]=clamp(friendshipOf(id)+n,0,100)}
function customerById(id){return ORDER_CUSTOMERS.find(x=>x.id===id)||ORDER_CUSTOMERS[0]}
function customerBadgeHtml(id){const c=customerById(id);const asset=farmAssetMarkup(`npc.${id}`,'farm-npc-asset');return asset||`<div class="npc-badge">${c.emoji}</div>`}
function customerTier(id){const f=friendshipOf(id);return f>=80?'Thân thiết':f>=50?'Quen thân':f>=20?'Quý mến':'Làm quen'}
function profileSummaryText(){return `${state.avatar||'👨‍🌾'} ${state.playerName||'Chủ vườn'} · ${state.farmName||'Nông Trại Nhỏ'}`}

function seasonBase(){return state.season||(state.season={chapter:1,name:'Mùa Khởi Hành',points:0,stars:0,completed:0,goal:SEASON_GOAL_BASE,activePerks:[],choiceQueue:[],history:[],nextStoryAt:3,metaBoost:0})}
function seasonNames(ch){return ['Mùa Khởi Hành','Mùa Chợ Sớm','Mùa Hàng Xóm','Mùa Thu Trái Ngọt','Mùa Phố Nhỏ'][Math.max(0,(ch-1)%5)]}
function availableSeasonPerks(){return [
{id:'fast_root',name:'Rau củ bén rễ',desc:'Cà rốt, khoai tây, khoai lang, hành tây nhanh hơn 15%.',type:'speed',cropIds:['carrot','potato','sweet_potato','onion'],value:.15},
{id:'leafy_fresh',name:'Lá non tươi tốt',desc:'Xà lách, bắp cải, bắp, cà chua +1 yield.',type:'yield',cropIds:['lettuce','cabbage','corn','tomato'],value:1},
{id:'fruit_basket',name:'Giỏ trái đầy',desc:'Dâu, nho, cam, táo, xoài, việt quất +1 yield.',type:'yield',cropIds:['strawberry','grape','orange','apple','mango','blueberry'],value:1},
{id:'neighbor_smile',name:'Hàng xóm quý mến',desc:'Mọi đơn hàng +25% friendship.',type:'friendship',value:.25},
{id:'quick_dispatch',name:'Giao nhanh',desc:'Đơn hồi nhanh hơn 25%.',type:'cooldown',value:.25},
{id:'market_insight',name:'Mắt nhìn thị trường',desc:'Bán chợ được +12% giá.',type:'market',value:.12},
{id:'carefree_rain',name:'Mưa thuận gió hòa',desc:'Cây chậm khô hơn 20%.',type:'care',value:.20},
{id:'bonus_material',name:'Xưởng tái chế',desc:'Đơn có 30% cơ hội +1 vật liệu.',type:'material',value:.30}
]}
function perkActive(id){return seasonBase().activePerks.some(p=>p.id===id)}
function seasonModifier(type,cropId=''){const perks=seasonBase().activePerks||[];let value=0;for(const p of perks){if(p.type!==type)continue;if(p.cropIds&&cropId&&!p.cropIds.includes(cropId))continue;value+=p.value||0}return value}
function generateSeasonChoices(){const pool=availableSeasonPerks().filter(p=>!perkActive(p.id));const seed=now()+seasonBase().completed*13+state.level*17;const picks=[];for(let i=0;i<3&&pool.length;i++){const idx=Math.floor(seeded(seed+i*19)*pool.length);picks.push(pool.splice(idx,1)[0])}seasonBase().choiceQueue=picks}
function chooseSeasonPerk(id){const s=seasonBase();const perk=(s.choiceQueue||[]).find(p=>p.id===id);if(!perk)return; s.activePerks.push(perk); s.history.push({season:s.chapter,perk:id,at:now()}); s.choiceQueue=[]; save(); renderOrders(); toast(`🌟 Nhận perk: ${perk.name}`)}
function advanceSeasonProgress(customerId){const s=seasonBase(); s.completed++; s.points+=1; if(s.completed>=s.nextStoryAt){ s.nextStoryAt+=3; if(!s.choiceQueue.length) generateSeasonChoices(); }
 if(s.completed>=s.goal){ const gained=1+Math.floor(s.chapter/3); s.stars+=gained; const prev=s.chapter; s.chapter++; s.name=seasonNames(s.chapter); s.completed=0; s.points=0; s.goal=SEASON_GOAL_BASE+Math.min(8,Math.floor(s.chapter/2)); s.activePerks=[]; s.choiceQueue=[]; s.history.push({season:prev,finished:true,at:now()}); toast(`🏅 Hoàn tất ${seasonNames(prev)} · +${gained} Huy hiệu mùa!`,'warning'); }
}
function seasonSummaryHtml(){ const s=seasonBase(); const perkHtml=(s.activePerks||[]).length?(s.activePerks.map(p=>`<span class="season-pill">${p.name}</span>`).join('')):'<span class="muted">Chưa có perk mùa</span>'; const choiceHtml=(s.choiceQueue||[]).length?`<div class="season-choices">${s.choiceQueue.map(p=>`<button class="season-choice" data-perk-choice="${p.id}"><b>${p.name}</b><span>${p.desc}</span></button>`).join('')}</div>`:''; return `<div class="order-card season-card"><h3>🌼 ${s.name}</h3><div class="muted">Mùa ${s.chapter} · Hoàn thành ${s.completed}/${s.goal} đơn · Huy hiệu ${s.stars}</div><div class="friend-row"><span class="friend-chip">⭐ ${s.completed}/${s.goal}</span><div class="friend-bar"><span style="width:${Math.min(100,Math.round(s.completed/s.goal*100))}%"></span></div></div><div class="order-note">Mỗi ${SEASON_QUEST_STEP} đơn sẽ có 1 lựa chọn perk tạm thời cho mùa hiện tại. Kết thúc mùa sẽ reset perk nhưng giữ Huy hiệu mùa.</div><div class="season-perks">${perkHtml}</div>${choiceHtml}</div>` }
function customerStory(customer){const friend=friendshipOf(customer.id);const stories=customer.story||[];let extra=''; if(friend>=80)extra=' Hai bên giờ đã thân thiết nên khách sẵn sàng gửi những đơn đẹp và thưởng hào phóng hơn.'; else if(friend>=50)extra=' Khách đã bắt đầu tin tưởng lịch giao hàng của bạn.'; else if(friend>=20)extra=' Quan hệ đang tiến triển tích cực qua từng đơn giao đúng hẹn.'; return `${stories[Math.floor(seeded(now()/600000+friend)*stories.length)]||customer.likes}${extra}`}

function expNeed(level){return 80+level*45+Math.floor(level*level*4)}
function addExp(n){state.exp+=n;let up=0;while(state.exp>=expNeed(state.level)){state.exp-=expNeed(state.level);state.level++;up++}if(up){toast(`🎉 Lên Cấp ${state.level}!`);checkAchievements();renderAll()}}
function speedMult(){return (SPEED_UPGRADES[state.speedLevel]?.mult||1)*(1+(seasonBase().metaBoost||0))}
function cropUnits(){let n=0;for(const q of Object.values(state.warehouse.crops))n+=q.normal+q.fresh+q.premium;return n}
function materialUnits(){return Object.values(state.warehouse.materials).reduce((a,b)=>a+b,0)}
function warehouseUsed(){return cropUnits()+Math.ceil(materialUnits()/10)}
function warehouseFree(){return Math.max(0,state.warehouse.capacity-warehouseUsed())}
function getWeather(){const key=Math.floor(now()/(6*hour));const idx=Math.abs((key*17+11)%WEATHER_CONFIG.length);return {key:String(key),...WEATHER_CONFIG[idx]}}
function weatherSync(){const w=getWeather();if(state.lastWeatherKey!==w.key){if(w.id==='rain'){for(const p of state.plots)if(p.cropId&&!p.deadAt)p.wateredAt=now();toast('🌧️ Trời mưa: cây trên ruộng đã được tưới.')}state.lastWeatherKey=w.key;save()}return w}
function careStatus(p,t=now()){if(!p.cropId)return {id:'empty',label:'Đất trống'};if(p.deadAt)return {id:'dead',label:'Đã chết'};const c=cropById[p.cropId],w=getWeather(),hours=(t-(p.wateredAt||p.plantedAt))/hour*w.waterFactor;const safe=(18+(1-c.waterNeed)*9)*(1+seasonModifier('care'));const bias=((c.disease||0.2)-0.18)*12;const dryAt=safe+Math.max(4,6-bias*.25);const weakAt=safe+Math.max(10,14-bias*.65);const diseaseAt=safe+Math.max(17,24-bias);const deadAt=safe+Math.max(28,36-bias*1.15);if(hours>deadAt)return {id:'dead',label:'Chết vì thiếu nước',dead:true,reason:`Thiếu nước quá lâu (${Math.floor(hours)} giờ).`};if(hours>diseaseAt)return {id:'disease',label:'Bệnh nặng',disease:true};if(hours>weakAt)return {id:'weak',label:'Suy yếu',disease:true};if(hours>dryAt)return {id:'dry',label:'Khô'};if(hours>safe)return {id:'slightly',label:'Hơi khô'};return {id:'good',label:'Đủ nước'}}
function growthProgress(p,t=now()){if(!p.cropId||p.deadAt)return 0;const c=cropById[p.cropId],w=getWeather();const perkSpeed=1+seasonModifier('speed',c.id);return clamp((t-p.plantedAt)/(c.growMin*60000)*speedMult()*perkSpeed*w.growth,0,1)}
function syncPlotHealth(){let changed=false;for(const p of state.plots){if(!p.cropId||p.deadAt)continue;const s=careStatus(p);if(s.dead){p.deadAt=now();p.deadReason=s.reason;changed=true}else if(s.disease&&!p.diseaseAt){p.diseaseAt=now();changed=true}}if(changed)save()}
function qualityFor(p){const s=careStatus(p),w=getWeather();let score=.66+w.quality;if(s.id==='slightly')score-=.08;if(s.id==='dry')score-=.20;if(s.id==='weak'||s.id==='disease')score-=.35;if(p.diseaseAt)score-=.12;score=clamp(score,.1,.98);return score>.83?'premium':score>.52?'fresh':'normal'}
function qualityName(q){return q==='premium'?'Hảo hạng':q==='fresh'?'Tươi':'Thường'}
function cropQty(id){const q=state.warehouse.crops[id];return q.normal+q.fresh+q.premium}
function takeCrop(id,count){let left=count,q=state.warehouse.crops[id];for(const k of ['normal','fresh','premium']){const use=Math.min(q[k],left);q[k]-=use;left-=use;if(!left)break}return left===0}
function hasCosts({gold=0,diamond=0,materials={},crops={}}={}){if(state.gold<gold||state.diamonds<diamond)return false;for(const [k,v] of Object.entries(materials))if((state.warehouse.materials[k]||0)<v)return false;for(const [k,v] of Object.entries(crops))if(cropQty(k)<v)return false;return true}
function spendCosts(cost){if(!hasCosts(cost))return false;state.gold-=cost.gold||0;state.diamonds-=cost.diamond||0;for(const [k,v] of Object.entries(cost.materials||{}))state.warehouse.materials[k]-=v;for(const [k,v] of Object.entries(cost.crops||{}))takeCrop(k,v);return true}
function addMaterial(id,n){state.warehouse.materials[id]=(state.warehouse.materials[id]||0)+n}
function formatDuration(ms){if(ms<=0)return 'Sẵn sàng';const m=Math.ceil(ms/60000);if(m<60)return `${m} phút`;const h=Math.floor(m/60),mm=m%60;return `${h}g ${mm}p`}
function seeded(seed){let x=Math.sin(seed)*10000;return x-Math.floor(x)}
function marketInfo(c){const period=Math.floor(now()/(6*hour)),r=seeded(period*101+c.level*17+c.id.length*13),bonus=seasonModifier('market'),mult=.62+r*.28+bonus;return {mult,price:Math.max(1,Math.round(c.basePrice*mult)),trend:mult>0.84?'↑ Giá khá':mult<0.70?'↓ Giá thấp':'→ Ổn định'}}
function materialExchangeCost(id){const keys=['carrot','potato','corn','tomato','cabbage','strawberry','pumpkin','watermelon','orange','grape'];const crop=keys[Object.keys(MATERIAL_CONFIG).indexOf(id)%keys.length];return {crop,qty:6+Object.keys(MATERIAL_CONFIG).indexOf(id)*2}}
function levelCropPool(){return CROP_CONFIG.filter(c=>c.level<=state.level)}
function plantedSummary(){const map={};for(const p of state.plots){if(!p.cropId||p.deadAt)continue;const rest=Math.max(0,1-growthProgress(p));(map[p.cropId]??=[]).push({remainingMin:Math.ceil(rest*cropById[p.cropId].growMin),yield:cropById[p.cropId].yield})}return map}
function customerCropPool(customer){const unlocked=levelCropPool();const preferred=new Set(customer.preferred||[]);return unlocked.filter(c=>preferred.has(c.id)||customer.groups?.includes(c.group))}
function chooseOrderCrops(customer,seed){const planted=plantedSummary();const pool=customerCropPool(customer);const enriched=pool.map(c=>{const inStock=cropQty(c.id);const future=(planted[c.id]||[]).reduce((a,b)=>a+b.yield,0);const score=1+(customer.preferred.includes(c.id)?2.6:0)+(inStock>0?2.2:0)+(future>0?1.6:0)+(c.growMin<=90?0.9:0)-(c.growMin>360&&inStock===0&&future===0?1.8:0);return {crop:c,inStock,future,score}}).filter(x=>x.score>0.2);enriched.sort((a,b)=>b.score-a.score);const count=clamp(1+Math.floor(seeded(seed+51)*3),1,Math.min(3,enriched.length||1));const picked=[];for(const item of enriched){if(picked.length>=count)break;if(!picked.find(x=>x.crop.id===item.crop.id))picked.push(item)}return picked.length?picked:enriched.slice(0,1)}
function estimatePlotLoad(){let growing=0;for(const p of state.plots.slice(0,state.unlockedPlotCount))if(p.cropId&&!p.deadAt&&growthProgress(p)<1)growing++;return growing}
function orderDifficulty(req){const entries=Object.entries(req||{}); if(!entries.length)return 1; const total=entries.reduce((a,[,q])=>a+q,0); const grow=Math.max(...entries.map(([id])=>cropById[id].growMin)); return clamp(Math.round(total/3 + grow/20),1,10)}
function orderRespawnMinutes(order){const diff=order?.difficulty||1; const min=diff<=3?1:diff<=6?3:6; const max=diff<=3?3:diff<=6?6:10; return min+Math.floor(Math.random()*(max-min+1)) }
function levelCropPool(){return CROP_CONFIG.filter(c=>c.level<=state.level)}
function plantedSummary(){const map={};for(const p of state.plots){if(!p.cropId||p.deadAt)continue;const rest=Math.max(0,1-growthProgress(p));(map[p.cropId]??=[]).push({remainingMin:Math.ceil(rest*cropById[p.cropId].growMin),yield:cropById[p.cropId].yield+seasonModifier('yield',p.cropId)})}return map}
function customerCropPool(customer){const unlocked=levelCropPool();const preferred=new Set(customer.preferred||[]);return unlocked.filter(c=>preferred.has(c.id)||customer.groups?.includes(c.group))}
function chooseOrderCrops(customer,seed){const planted=plantedSummary();const pool=customerCropPool(customer);const enriched=pool.map(c=>{const inStock=cropQty(c.id);const future=(planted[c.id]||[]).reduce((a,b)=>a+b.yield,0);const score=1+(customer.preferred.includes(c.id)?2.6:0)+(inStock>0?2.2:0)+(future>0?1.7:0)+(c.growMin<=25?1.1:0)+(c.growMin<=60?0.5:0);return {crop:c,inStock,future,score}}).filter(x=>x.score>0.2);enriched.sort((a,b)=>b.score-a.score);const count=clamp(1+Math.floor(seeded(seed+51)*3),1,Math.min(3,enriched.length||1));const picked=[];for(const item of enriched){if(picked.length>=count)break;if(!picked.find(x=>x.crop.id===item.crop.id))picked.push(item)}return picked.length?picked:enriched.slice(0,1)}
function estimatePlotLoad(){let growing=0;for(const p of state.plots.slice(0,state.unlockedPlotCount))if(p.cropId&&!p.deadAt&&growthProgress(p)<1)growing++;return growing}
function orderTitles(customer){return ['Đơn hàng thân quen','Đơn cần gấp vừa phải','Lời nhờ từ '+customer.name,'Đơn hỗ trợ cộng đồng']}
function generateOrder(slot){const seed=Math.floor(now()/60000)+slot*91+state.stats.orders*13+state.level*7;const eligibleCustomers=ORDER_CUSTOMERS.filter(c=>customerCropPool(c).length); const customerSource=eligibleCustomers.length?eligibleCustomers:ORDER_CUSTOMERS;const customer=customerSource[Math.floor(seeded(seed+8)*customerSource.length)];const picks=chooseOrderCrops(customer,seed);const req={};const planted=plantedSummary();let deadlineMin=8;let value=0;if(!picks.length){const fallback=levelCropPool()[0]||CROP_CONFIG[0];req[fallback.id]=3;value=fallback.basePrice*3;deadlineMin=Math.max(deadlineMin,Math.min(120,Math.round(fallback.growMin*1.25+2)));const difficulty=orderDifficulty(req);return {id:`o-${slot}-${now()}`,customerId:customer.id,customer:customer.name,title:'Đơn hàng thân quen',req,gold:Math.round(value*customer.rewardMult*1.45),exp:Math.max(8,Math.round(value/14)),material:{id:Object.keys(MATERIAL_CONFIG)[0],qty:1},deadlineAt:now()+deadlineMin*60000,friendshipGain:3,note:customerStory(customer),difficulty}}for(let idx=0;idx<picks.length;idx++){const item=picks[idx],c=item.crop;const futureList=(planted[c.id]||[]);const futureYield=item.future;const stocked=item.inStock;let target=Math.max(2,Math.round((1.6+idx+seeded(seed+idx*9)*1.6)+(c.level/5)));if(stocked>0)target=Math.max(target,Math.min(stocked+Math.max(1,Math.round(stocked*.35)), stocked+5));if(futureYield>0)target=Math.max(target,Math.min(stocked+futureYield, stocked+futureYield+2));if(c.growMin>90&&stocked===0&&futureYield===0)target=Math.min(target,3+Math.floor(seeded(seed+idx*31)*2));target=clamp(target,2, Math.max(4,8+Math.floor(state.level/3)));req[c.id]=target;value+=c.basePrice*target;const missing=Math.max(0,target-stocked);let est=c.growMin; if(futureYield>=missing&&futureList.length){est=Math.max(1,Math.round(futureList.reduce((a,b)=>a+b.remainingMin,0)/futureList.length))}else if(futureYield>0&&missing>futureYield&&futureList.length){est=Math.max(c.growMin, Math.round(futureList.reduce((a,b)=>a+b.remainingMin,0)/futureList.length)+c.growMin*.45)}deadlineMin=Math.max(deadlineMin, Math.min(120, Math.round(est*1.25 + 2)))}const difficult=estimatePlotLoad()>state.unlockedPlotCount*.66||Object.values(req).some(v=>v>=8);deadlineMin=clamp(deadlineMin+(difficult?3:0),8,120);const friend=friendshipOf(customer.id), friendBoost=1+Math.min(.22,friend/220);const mats=Object.keys(MATERIAL_CONFIG);const mat=mats[Math.floor(seeded(seed+777)*Math.min(mats.length,Math.max(2,Math.floor(state.level/2)+2)))];const gold=Math.round(value*(1.50+seeded(seed+2)*.24)*customer.rewardMult*friendBoost);const exp=Math.max(8,Math.round(value/13));const friendshipGain=Math.round((2+Math.floor(picks.length)+Math.floor(seeded(seed+19)*3))*(1+seasonModifier('friendship')));let materialQty=1+Math.floor((state.level>=10?1:0)+(seeded(seed+3)*2));if(Math.random()<seasonModifier('material'))materialQty++;const titlePool=orderTitles(customer);const note=customerStory(customer);const difficulty=orderDifficulty(req);return {id:`o-${slot}-${now()}`,customerId:customer.id,customer:customer.name,title:titlePool[Math.floor(seeded(seed+9)*titlePool.length)],req,gold,exp,material:{id:mat,qty:materialQty},deadlineAt:now()+deadlineMin*60000,friendshipGain,note,difficulty}}
function ensureOrders(){let changed=false;for(let i=0;i<ORDER_SLOT_COUNT;i++){const o=state.orders[i];if(o&&o.deadlineAt&&o.deadlineAt<=now()){const cd=orderRespawnMinutes(o);state.orders[i]=null;state.orderCooldown[i]=now()+cd*60000;changed=true}if(!state.orders[i]&&now()>=(state.orderCooldown[i]||0)){state.orders[i]=generateOrder(i);changed=true}}if(changed)save()}
function completeOrder(i){const o=state.orders[i];if(!o)return;for(const [id,q] of Object.entries(o.req))if(cropQty(id)<q)return guide('Chưa thể giao đơn',`Bạn chưa đủ ${cropById[id].name}. Hiện có ${cropQty(id)}, cần ${q}.`,['Trồng thêm nông sản còn thiếu.','Kiểm tra Kho trước khi giao.']);const cropCost=Object.fromEntries(Object.entries(o.req));if(!spendCosts({crops:cropCost}))return;state.gold+=o.gold;addExp(o.exp);addMaterial(o.material.id,o.material.qty);addFriendship(o.customerId,o.friendshipGain||3);advanceSeasonProgress(o.customerId);state.stats.orders++;const cd=orderRespawnMinutes(o);state.orders[i]=null;state.orderCooldown[i]=now()+cd*60000;toast(`✅ Giao đơn thành công · +${fmt(o.gold)} Vàng · ❤️ +${o.friendshipGain||3} · đơn mới sau ${cd} phút`);checkAchievements();save();renderAll()}
function discardOrder(i){if(!state.orders[i])return;const o=state.orders[i];const cd=Math.min(10,orderRespawnMinutes(o)+1);state.orders[i]=null;state.orderCooldown[i]=now()+cd*60000;save();renderOrders();toast(`Đã bỏ đơn. Đơn mới sau khoảng ${cd} phút.`,'warning')}
function plant(i,id){const c=cropById[id],p=state.plots[i];if(!c||c.level>state.level)return guide('Chưa mở khóa',`${c?.name||'Cây này'} mở khóa ở Cấp ${c?.level||'?'}.`,['Hoàn thành đơn hàng và thu hoạch để nhận EXP.']);if(p.cropId)return;if(state.gold<c.seedCost)return guide('Chưa đủ Vàng',`Bạn cần thêm ${fmt(c.seedCost-state.gold)} Vàng để mua hạt ${c.name}.`,['Bán nông sản trong Chợ.','Hoàn thành đơn hàng.']);state.gold-=c.seedCost;state.plots[i]={...newPlot(i),cropId:id,plantedAt:now(),wateredAt:now()};state.stats.cropsPlanted++;save();renderAll();toast(`Đã gieo ${c.name}.`)}
function harvest(i){const p=state.plots[i];if(!p.cropId||p.deadAt)return;if(growthProgress(p)<1)return toast('Cây chưa trưởng thành.','warning');const c=cropById[p.cropId],gain=c.yield+seasonModifier('yield',c.id);if(warehouseFree()<gain)return guide('Kho đã đầy',`Kho hiện có ${warehouseUsed()}/${state.warehouse.capacity} chỗ. Cần ít nhất ${gain} chỗ để thu hoạch ${c.name}.`,['Bán bớt nông sản.','Giao đơn hàng.','Đổi nông sản lấy vật liệu.','Dùng 1 Kim Cương để mở thêm 5 chỗ.']);const q=qualityFor(p);state.warehouse.crops[c.id][q]+=gain;state.stats.harvested+=gain;addExp(c.exp);state.plots[i]=newPlot(i);toast(`🧺 +${gain} ${c.name} (${qualityName(q)})`);checkAchievements();save();renderAll()}
function water(i){const p=state.plots[i];if(!p.cropId||p.deadAt)return;p.wateredAt=now();toast('💧 Đã tưới cây.');save();renderFarm()}
function cure(i){const p=state.plots[i];if(!p.cropId||p.deadAt)return;const status=careStatus(p);if(!status.disease&&!p.diseaseAt)return toast('Cây chưa có dấu hiệu bệnh.');if(state.warehouse.materials.fertilizer>0)state.warehouse.materials.fertilizer--;else if(state.gold>=35)state.gold-=35;else return guide('Chưa thể chăm bệnh','Bạn cần 1 Phân hữu cơ hoặc 35 Vàng.',['Hoàn thành đơn hàng để nhận vật liệu.','Đổi nông sản lấy Phân hữu cơ.']);p.diseaseAt=0;p.treatedAt=now();p.wateredAt=now();toast('🌿 Cây đã được chăm bệnh và tưới lại.');save();renderAll()}
function clearDead(i){const p=state.plots[i];if(!p.deadAt)return;p.cropId=null;p.deadAt=0;p.deadReason='';p.plantedAt=0;p.wateredAt=0;p.diseaseAt=0;save();renderFarm();toast('Đã dọn cây chết.')}
function handlePlot(i){if(i>=state.unlockedPlotCount)return guide('Ô đất chưa mở','Bạn cần mở rộng ruộng trước.',['Vào Nâng cấp → Mở thêm đất.']);const p=state.plots[i];if(selectedAction==='water')return water(i);if(selectedAction==='cure')return cure(i);if(selectedAction==='clear')return clearDead(i);if(selectedAction==='harvest'&&p.cropId)return harvest(i);if(!p.cropId){if(selectedAction==='plant')return plant(i,selectedCrop);return toast('Chọn một loại hạt giống để gieo vào ô đất trống.','warning')}if(growthProgress(p)>=1)return harvest(i);toast('Cây đang lớn. Bạn có thể tưới nếu đất bắt đầu khô.','warning')}
function waterAll(){const living=state.plots.filter((p,i)=>i<state.unlockedPlotCount&&p.cropId&&!p.deadAt);if(!living.length)return toast('Không có cây cần tưới.');living.forEach(p=>p.wateredAt=now());save();renderFarm();toast(`💧 Đã tưới ${living.length} ô.`)}
function sellCrop(id,n){const available=cropQty(id),qty=n==='all'?available:Math.min(n,available);if(!qty)return;const c=cropById[id],m=marketInfo(c);takeCrop(id,qty);const gold=qty*m.price;state.gold+=gold;state.stats.sold+=qty;save();renderAll();toast(`💰 Bán ${qty} ${c.name} · +${fmt(gold)} Vàng`)}
function exchangeMaterial(id){const {crop,qty}=materialExchangeCost(id);if(cropQty(crop)<qty)return guide('Chưa đủ nông sản',`Cần ${qty} ${cropById[crop].name} để đổi 2 ${MATERIAL_CONFIG[id].name}.`,[`Hiện có: ${cropQty(crop)}.`]);takeCrop(crop,qty);addMaterial(id,2);save();renderAll();toast(`Đổi được 2 ${MATERIAL_CONFIG[id].name}.`)}
function expandWarehouse(){if(state.diamonds<1)return guide('Bạn chưa đủ Kim Cương','Kim Cương không mua bằng Vàng.',['Đổi nông sản + vật liệu ở Nâng cấp.','Hoàn thành thành tựu.']);const before=state.warehouse.capacity;if(!confirm(`Kho hiện tại: ${before}\nSau nâng cấp: ${before+5}\nDùng 1 Kim Cương?`))return;state.diamonds--;state.warehouse.capacity+=5;save();renderAll();toast('📦 Kho đã mở thêm 5 chỗ.')}
function craftDiamond(id){const r=DIAMOND_RECIPE_CONFIG.find(x=>x.id===id);if(!r||state.level<r.level)return;if(!hasCosts({crops:r.crops,materials:r.materials}))return guide('Chưa đủ nguyên liệu','Bạn chưa đủ nông sản hoặc vật liệu cho công thức này.',['Kiểm tra Kho.','Hoàn thành đơn hàng để nhận vật liệu.']);spendCosts({crops:r.crops,materials:r.materials});state.diamonds+=r.diamond;state.stats.diamondsMade+=r.diamond;save();checkAchievements();renderAll();toast(`💎 Nhận ${r.diamond} Kim Cương!`)}
function upgradeSpeed(){const next=SPEED_UPGRADES[state.speedLevel+1];if(!next)return toast('Đã đạt cấp tốc độ tối đa.');if(state.diamonds<next.cost)return guide('Chưa đủ Kim Cương',`Nâng tốc độ Cấp ${next.level} cần ${next.cost} Kim Cương.`,['Ưu tiên giữa Kho, Tốc độ và Nhà Vườn.']);if(!confirm(`Dùng ${next.cost} Kim Cương để tăng tốc độ cây lên ${Math.round(next.mult*100)}%?`))return;state.diamonds-=next.cost;state.speedLevel++;save();renderAll();toast('⚡ Tốc độ tăng trưởng đã được nâng vĩnh viễn.')}
function expandLand(){if(state.unlockedPlotCount>=MAX_PLOTS)return toast('Đã mở toàn bộ đất.');const step=state.unlockedPlotCount-INITIAL_PLOTS,cost=180+step*85,wood=Math.floor(step/3);if(!hasCosts({gold:cost,materials:{wood}}))return guide('Chưa thể mở đất',`Cần ${fmt(cost)} Vàng${wood?` và ${wood} Gỗ`:''}.`,['Hoàn thành đơn hàng để nhận Vàng và vật liệu.']);spendCosts({gold:cost,materials:{wood}});state.unlockedPlotCount++;save();renderAll();toast('🚩 Đã mở thêm 1 ô đất.')}
function villaStage(){let n=0;for(let i=1;i<=VILLA_CONFIG.length;i++){if(state.house.built?.[`villa_${i}`])n=i;else break}return Math.max(1,n)}
function villaStageAsset(stage){const s=clamp(stage||1,1,VILLA_CONFIG.length);return `assets/villa/stage_${String(s).padStart(2,'0')}.png`}
function buildVilla(id){const b=VILLA_CONFIG.find(x=>x.id===id);if(!b||state.house.built[id])return;const stage=villaStage(),next=VILLA_CONFIG[stage];if(!next||next.id!==id)return guide('Xây theo tiến độ',next?`Giai đoạn tiếp theo là “${next.name}”.`:'Nhà Vườn đã hoàn thiện.',['Các hạng mục được xây nối tiếp để hình ảnh phát triển đúng tiến độ.']);if(state.level<b.level)return guide('Chưa đủ cấp',`${b.name} mở xây từ Cấp ${b.level}.`,['Tích lũy EXP từ thu hoạch và đơn hàng.']);const cost={gold:b.gold,diamond:b.diamond,materials:b.materials};if(!hasCosts(cost))return guide('Chưa đủ nguyên liệu',`Bạn chưa đủ tài nguyên để xây ${b.name}.`,['Kiểm tra Vàng, Kim Cương và vật liệu.','Hoàn thành đơn hàng để bổ sung vật liệu.']);const materialText=Object.entries(b.materials||{}).map(([k,v])=>`${MATERIAL_CONFIG[k].name} ${v}`).join(' · ');const costText=[b.gold?`${fmt(b.gold)} Vàng`:'',b.diamond?`${b.diamond} Kim Cương`:'',materialText].filter(Boolean).join(' · ');if(!confirm(`Xây giai đoạn ${stage+1}/16 – “${b.name}”?${costText?`\n${costText}`:''}`))return;spendCosts(cost);state.house.built[id]=true;addExp(15+b.level);save();checkAchievements();renderAll();toast(`🏡 Hoàn tất ${b.name} · ${villaStage()}/16.`)}
const ACH=[
{id:'h100',name:'Mùa vụ đầu tiên',desc:'Thu hoạch 100 nông sản',test:s=>s.stats.harvested>=100,reward:{exp:80,material:['wood',3]}},
{id:'o20',name:'Người giao hàng',desc:'Hoàn thành 20 đơn',test:s=>s.stats.orders>=20,reward:{exp:120,diamond:1}},
{id:'d1',name:'Kim Cương đầu tiên',desc:'Tự đổi được Kim Cương',test:s=>s.stats.diamondsMade>=1,reward:{exp:70,material:['glass',2]}},
{id:'l10',name:'Nông dân Cấp 10',desc:'Đạt Cấp 10',test:s=>s.level>=10,reward:{diamond:1}},
{id:'v10',name:'Nhà Vườn 25%',desc:'Hoàn tất 4/16 giai đoạn',test:s=>[1,2,3,4].every(i=>s.house.built?.[`villa_${i}`]),reward:{diamond:1}},
{id:'v20',name:'Nhà Vườn 50%',desc:'Hoàn tất 8/16 giai đoạn',test:s=>Array.from({length:8},(_,i)=>i+1).every(i=>s.house.built?.[`villa_${i}`]),reward:{diamond:1}},
{id:'v30',name:'Nhà Vườn 75%',desc:'Hoàn tất 12/16 giai đoạn',test:s=>Array.from({length:12},(_,i)=>i+1).every(i=>s.house.built?.[`villa_${i}`]),reward:{diamond:2}},
{id:'v40',name:'Nhà Vườn hoàn chỉnh',desc:'Hoàn tất đủ 16 giai đoạn',test:s=>Array.from({length:16},(_,i)=>i+1).every(i=>s.house.built?.[`villa_${i}`]),reward:{diamond:3}}
];
function checkAchievements(){for(const a of ACH){if(state.achievements[a.id]||!a.test(state))continue;state.achievements[a.id]=true;if(a.reward.exp)state.exp+=a.reward.exp;if(a.reward.diamond)state.diamonds+=a.reward.diamond;if(a.reward.material)addMaterial(a.reward.material[0],a.reward.material[1]);toast(`🏆 Thành tựu: ${a.name}`)}save()}
function renderAll(){weatherSync();syncPlotHealth();ensureOrders();renderStatus();renderFarm();renderWarehouse();renderOrders();renderMarket();renderVilla();renderUpgrade();renderAchievements();renderHelp();renderTutorial()}
function renderStatus(){const w=getWeather();$('#goldStat').textContent=fmt(state.gold);$('#diamondStat').textContent=fmt(state.diamonds);$('#levelStat').textContent=state.level;$('#expStat').textContent=`${fmt(state.exp)}/${fmt(expNeed(state.level))}`;$('#warehouseStat').textContent=`${warehouseUsed()}/${state.warehouse.capacity}`;$('#weatherStat').textContent=`${w.icon} ${w.name}`;if($('#profileStat'))$('#profileStat').textContent=profileSummaryText()}
function renderSeedButtons(){const host=$('#seedList');host.innerHTML=CROP_CONFIG.map(c=>`<button class="seed-btn ${selectedCrop===c.id?'active':''} ${c.level>state.level?'locked':''}" data-crop="${c.id}" ${c.level>state.level?'disabled':''}><span class="seed-icon">${farmAssetMarkup(`crop.${c.id}.mature`)||cropSymbol(c)}</span><span><b>${c.name}</b><small>Cấp ${c.level} · ${fmt(c.seedCost)}G · ${formatDuration(c.growMin*60000)}</small></span></button>`).join('');host.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>{selectedCrop=b.dataset.crop;selectedAction='plant';setActiveAction();renderSeedButtons()})}
function setActiveAction(){const sickCount=state.plots.filter(p=>p.cropId&&!p.deadAt&&careStatus(p).disease).length;$$('.action-btn').forEach(b=>{b.classList.toggle('active',b.dataset.action===selectedAction);if(b.dataset.action==='cure'){b.classList.toggle('attention',sickCount>0);b.dataset.badge=sickCount>0?`(${sickCount})`:'';b.title=sickCount>0?`Có ${sickCount} cây đang bệnh. Chọn thao tác này rồi chạm vào ô có biểu tượng ⚠️.`:'Dùng khi ô đất có biểu tượng ⚠️ để cứu cây bị bệnh';}});const names={harvest:'Thu hoạch',water:'Tưới',cure:sickCount>0?`Chăm bệnh (${sickCount} cây cần xử lý)`:'Chăm bệnh',clear:'Dọn cây chết',plant:`Gieo ${cropById[selectedCrop]?.name||''}`};$('#selectedActionText').textContent=`Đang chọn: ${names[selectedAction]}`}
function renderFarm(){renderSeedButtons();setActiveAction();const host=$('#plotGrid');host.innerHTML='';for(let i=0;i<MAX_PLOTS;i++){const p=state.plots[i],locked=i>=state.unlockedPlotCount,el=document.createElement('button');el.className=`plot ${locked?'locked':''}`;el.dataset.i=i;el.innerHTML=`<canvas width="160" height="160"></canvas>${locked?'<span class="plot-badge">🔒</span>':''}<div class="plot-meta"><span></span><span></span></div>`;el.onclick=()=>handlePlot(i);host.appendChild(el);drawPlot(el.querySelector('canvas'),p,locked);const meta=el.querySelectorAll('.plot-meta span');if(locked){meta[0].textContent='Chưa mở';meta[1].textContent=''}else if(!p.cropId){meta[0].textContent='Đất trống';meta[1].textContent=''}else{const c=cropById[p.cropId],st=careStatus(p),prog=growthProgress(p);meta[0].textContent=c.name;meta[1].textContent=p.deadAt?'Đã chết':prog>=1?'Thu hoạch':`${Math.round(prog*100)}%`;const badge=el.querySelector('.plot-badge')||document.createElement('span');badge.className='plot-badge';badge.textContent=p.deadAt?'☠️':st.disease?'⚠️':st.id==='dry'||st.id==='slightly'?'💧':prog>=1?'✨':'';if(badge.textContent&&!badge.parentNode)el.appendChild(badge)}}}
function cropSymbol(c){return c.shape==='root'?'🌱':c.shape==='corn'?'🌽':c.shape==='berry'?'🍓':c.shape==='melon'?'🍈':c.shape==='vine'?'🍇':c.shape==='tree'?'🌳':c.shape==='cactus'?'🌵':'🌿'}
function drawPlot(canvas,p,locked){const x=canvas.getContext('2d'),W=canvas.width,H=canvas.height;x.clearRect(0,0,W,H);if(locked){x.fillStyle='#dfe7e1';x.fillRect(0,0,W,H);x.fillStyle='#b9c8bf';for(let i=0;i<5;i++){x.fillRect(10+i*31,20,18,110)}return}const wet=p.cropId?clamp(1-(now()-(p.wateredAt||p.plantedAt))/(40*hour),0,1):.5;const g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,wet>.4?'#7b5b3c':'#9d754d');g.addColorStop(1,'#5b422e');x.fillStyle=g;x.fillRect(0,0,W,H);x.strokeStyle='rgba(255,255,255,.08)';for(let i=15;i<W;i+=28){x.beginPath();x.moveTo(i,0);x.lineTo(i-10,H);x.stroke()}if(!p.cropId)return;const c=cropById[p.cropId],prog=growthProgress(p),st=careStatus(p),stage=p.deadAt?4:prog<.18?0:prog<.50?1:prog<.90?2:3,assetId=`crop.${c.id}.${CROP_STAGE_ASSET[stage]}`;const stageScale=[.36,.56,.78,1,.92][stage];const assetSize=Math.round(124*stageScale);const drewAsset=drawFarmAsset(x,assetId,{x:W/2,y:H-12,width:assetSize,height:assetSize,alpha:p.deadAt?.68:1});if(!drewAsset)drawCrop(x,c,stage,st,p.deadAt);else if(st.disease&&!p.deadAt)drawDiseaseMarks(x);if(prog<1&&!p.deadAt){x.fillStyle='rgba(255,255,255,.88)';x.fillRect(12,H-17,W-24,6);x.fillStyle='#59bd8c';x.fillRect(12,H-17,(W-24)*prog,6)}}
function drawDiseaseMarks(ctx){ctx.fillStyle='#f4c04f';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(58+i*14,66+(i%2)*11,3.2,0,Math.PI*2);ctx.fill()}}
function drawCrop(ctx,c,stage,st,dead){ctx.save();ctx.translate(80,83);if(dead){ctx.globalAlpha=.55;ctx.filter='grayscale(1)'}const scale=[.35,.58,.78,1,1][stage];ctx.scale(scale,scale);ctx.lineCap='round';ctx.strokeStyle=dead?'#6d604d':c.colors[0];ctx.fillStyle=dead?'#7e715d':c.colors[0];ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(0,45);ctx.lineTo(0,-15);ctx.stroke();for(const side of [-1,1]){ctx.beginPath();ctx.ellipse(side*17,-6,19,9,side*.5,0,Math.PI*2);ctx.fill()}ctx.fillStyle=dead?'#756658':c.colors[1];if(stage>=2){if(['root','berry','corn','melon','pine','vine','tree','cactus'].includes(c.shape)){const count=c.shape==='berry'||c.shape==='vine'?5:c.shape==='tree'?4:2;for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2-Math.PI/2,rx=c.shape==='tree'?28:22,ry=c.shape==='tree'?18:20;ctx.beginPath();ctx.ellipse(Math.cos(a)*rx,Math.sin(a)*ry+2,c.shape==='root'?10:9,c.shape==='root'?14:9,0,0,Math.PI*2);ctx.fill()}}else{for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse((i-1.5)*10,-12+Math.abs(i-1.5)*4,17,11,i*.4,0,Math.PI*2);ctx.fill()}}}if(st.disease&&!dead){ctx.fillStyle='#f4c04f';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(-22+i*14,-8+(i%2)*11,3.2,0,Math.PI*2);ctx.fill()}}ctx.restore()}
function renderWarehouse(){const used=warehouseUsed();$('#warehouseUsage').textContent=`Đã dùng ${used}/${state.warehouse.capacity} · Còn ${warehouseFree()} chỗ`;$('#warehouseCrops').innerHTML=CROP_CONFIG.filter(c=>cropQty(c.id)>0).map(c=>{const q=state.warehouse.crops[c.id];return `<div class="list-row"><div><b>${c.name}</b><div class="muted">Thường ${q.normal} · Tươi ${q.fresh} · Hảo hạng ${q.premium}</div></div><b>${cropQty(c.id)}</b></div>`}).join('')||'<p class="muted">Kho chưa có nông sản.</p>';$('#materialsList').innerHTML=Object.entries(MATERIAL_CONFIG).map(([id,m])=>`<div class="material">${farmAssetMarkup(`material.${id}`)||m.icon} <b>${m.name}</b><div>${fmt(state.warehouse.materials[id])}</div></div>`).join('')}
function renderOrders(){ensureOrders();$('#ordersList').innerHTML=seasonSummaryHtml()+state.orders.map((o,i)=>{if(!o){const left=Math.max(0,state.orderCooldown[i]-now());return `<div class="order-card"><h3>Đang chờ đơn mới</h3><p class="muted">Đơn mới sau ${formatDuration(left)}</p><div class="slot-lock-note">Mỗi đơn sẽ quay lại sau khoảng 1–10 phút tùy độ khó.</div></div>`}const customer=customerById(o.customerId);const left=Math.max(0,(o.deadlineAt||0)-now());const ready=Object.entries(o.req).every(([id,q])=>cropQty(id)>=q);return `<div class="order-card ${ready?'ready':''}">${ready?'<div class="order-watermark">ĐỦ</div>':''}<div class="order-head">${customerBadgeHtml(customer.id)}<div><h3>${o.customer}</h3><div class="muted">${o.title}</div><small class="deadline">⏱ ${formatDuration(left)} · ${customerTier(customer.id)} · Độ khó ${o.difficulty||1}/10</small></div></div><div class="friend-row"><span class="friend-chip">❤️ ${friendshipOf(customer.id)}/100</span><div class="friend-bar"><span style="width:${friendshipOf(customer.id)}%"></span></div></div><div class="order-note">${o.note||customer.likes}</div>${Object.entries(o.req).map(([id,q])=>`<div class="req-line"><span>${cropById[id].name}</span><b>${cropQty(id)}/${q}</b></div>`).join('')}<div class="reward">💰 ${fmt(o.gold)} · EXP ${fmt(o.exp)} · ❤️ +${o.friendshipGain||3} · ${farmAssetMarkup(`material.${o.material.id}`)||MATERIAL_CONFIG[o.material.id].icon} ${o.material.qty} ${MATERIAL_CONFIG[o.material.id].name}</div><div class="row-actions"><button class="mini-btn" data-discard="${i}">Bỏ đơn</button><button class="primary-btn" data-complete="${i}">Giao đơn</button></div></div>`}).join('');$$('[data-complete]').forEach(b=>b.onclick=()=>completeOrder(+b.dataset.complete));$$('[data-discard]').forEach(b=>b.onclick=()=>discardOrder(+b.dataset.discard));$$('[data-perk-choice]').forEach(b=>b.onclick=()=>chooseSeasonPerk(b.dataset.perkChoice))}
function renderMarket(){$('#marketList').innerHTML=CROP_CONFIG.filter(c=>cropQty(c.id)>0).map(c=>{const m=marketInfo(c);return `<div class="list-row"><div><b>${c.name}</b><div class="muted">Có ${cropQty(c.id)} · ${m.trend} · ${fmt(m.price)}G/đv · Bán chợ chủ yếu để xả hàng dư</div></div><div class="row-actions"><button class="mini-btn" data-sell="${c.id}:1">Bán 1</button><button class="mini-btn" data-sell="${c.id}:10">Bán 10</button><button class="mini-btn" data-sell="${c.id}:all">Bán hết</button></div></div>`}).join('')||'<p class="muted">Chưa có nông sản để bán.</p>';$$('[data-sell]').forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.sell.split(':');sellCrop(id,n==='all'?'all':+n)});$('#materialExchange').innerHTML=Object.entries(MATERIAL_CONFIG).map(([id,m])=>{const x=materialExchangeCost(id);const icon=farmAssetMarkup(`material.${id}`)||m.icon;return `<div class="list-row"><div>${icon} <b>${m.name}</b><div class="muted">${x.qty} ${cropById[x.crop].name} → 2 ${m.name}</div></div><button class="mini-btn" data-mex="${id}">Đổi</button></div>`}).join('');$$('[data-mex]').forEach(b=>b.onclick=()=>exchangeMaterial(b.dataset.mex))}
function renderVilla(){const stage=villaStage(),total=VILLA_CONFIG.length,pct=Math.round(stage/total*100),next=VILLA_CONFIG[stage];$('#villaProgress').textContent=`${stage}/${total} giai đoạn · ${pct}%`;const img=$('#villaStageImage');if(img){img.src=villaStageAsset(stage);img.alt=`Nhà Vườn – giai đoạn ${stage}/${total}`};const label=$('#villaStageLabel');if(label)label.textContent=stage>=total?'Nhà Vườn đã hoàn thiện':`Hiện tại: ${VILLA_CONFIG[Math.max(0,stage-1)]?.name||'Khu đất'} · Tiếp theo: ${next?.name||''}`;$('#villaList').innerHTML=VILLA_CONFIG.map((b,i)=>{const no=i+1,done=no<=stage,isNext=no===stage+1,locked=no>stage+1;const mat=Object.entries(b.materials||{}).map(([k,v])=>`${MATERIAL_CONFIG[k].name} ${v}`).join(' · ');const cost=[b.gold?`${fmt(b.gold)}G`:'',b.diamond?`${b.diamond}💎`:'',mat].filter(Boolean).join(' · ')||'Đã có sẵn';return `<div class="build-row villa-stage-row ${done?'built':''} ${isNext?'next':''} ${locked?'locked-stage':''}"><div class="villa-stage-no">${String(no).padStart(2,'0')}</div><div class="villa-stage-info"><b>${done?'✓ ':''}${b.name}</b><div class="muted">${b.category} · Cấp ${b.level} · ${b.desc||''}</div><div class="cost">${cost}</div></div>${isNext?`<button class="mini-btn primary-stage-btn" data-build="${b.id}">Xây</button>`:done?'<span class="villa-stage-status done">Xong</span>':'<span class="villa-stage-status">Khóa</span>'}</div>`}).join('');$$('[data-build]').forEach(b=>b.onclick=()=>buildVilla(b.dataset.build));const bar=$('#villaStageBar');if(bar)bar.style.width=`${pct}%`}
function drawVilla(){renderVilla()}
function renderUpgrade(){const cur=SPEED_UPGRADES[state.speedLevel],next=SPEED_UPGRADES[state.speedLevel+1];$('#speedUpgrade').innerHTML=`<div class="upgrade-box"><b>⚡ Tốc độ cây: ${Math.round(cur.mult*100)}%</b><p class="muted">Nâng cấp vĩnh viễn, chỉ dùng Kim Cương.</p>${next?`<button id="speedBtn" class="primary-btn">Lên ${Math.round(next.mult*100)}% · ${next.cost} 💎</button>`:'<b>Đã tối đa</b>'}</div>`;if($('#speedBtn'))$('#speedBtn').onclick=upgradeSpeed;const step=state.unlockedPlotCount-INITIAL_PLOTS,cost=180+step*85,wood=Math.floor(step/3);$('#landUpgrade').innerHTML=`<b>🚩 Diện tích: ${state.unlockedPlotCount}/${MAX_PLOTS} ô</b><p class="muted">Mở đất dùng Vàng${wood?' + Gỗ':''}, không dùng Kim Cương.</p><button id="landBtn" class="primary-btn" ${state.unlockedPlotCount>=MAX_PLOTS?'disabled':''}>Mở 1 ô · ${fmt(cost)}G${wood?` · ${wood} Gỗ`:''}</button>`;$('#landBtn').onclick=expandLand;$('#diamondRecipes').innerHTML=DIAMOND_RECIPE_CONFIG.map(r=>`<div class="recipe"><b>${r.name}</b><div class="muted">Mở từ Cấp ${r.level} · Nhận ${r.diamond} 💎</div><div class="cost">${Object.entries(r.crops).map(([id,q])=>`${cropById[id].name} ${q}`).join(' · ')} · ${Object.entries(r.materials).map(([id,q])=>`${MATERIAL_CONFIG[id].name} ${q}`).join(' · ')}</div><button class="mini-btn" data-craft="${r.id}" ${state.level<r.level?'disabled':''}>Đổi</button></div>`).join('');$$('[data-craft]').forEach(b=>b.onclick=()=>craftDiamond(b.dataset.craft))}
function renderAchievements(){$('#achievementsList').innerHTML=ACH.map(a=>`<div class="achievement ${state.achievements[a.id]?'done':''}"><b>${state.achievements[a.id]?'🏆':'○'} ${a.name}</b><div>${a.desc}</div></div>`).join('')}
function renderHelp(){$('#helpList').innerHTML=Object.entries(HELP_CONFIG).map(([k,arr])=>`<details><summary>${({start:'Bắt đầu chơi',crop:'Trồng cây',water:'Tưới nước',disease:'Bệnh cây',warehouse:'Kho',orders:'Đơn hàng',diamond:'Kim Cương',villa:'Nhà Vườn',speed:'Nâng cấp tốc độ',material:'Vật liệu',weather:'Thời tiết',dead:'Vì sao cây chết?'})[k]}</summary><ul>${arr.map(v=>`<li>${v}</li>`).join('')}</ul></details>`).join('')}
function renderTutorial(){const b=$('#tutorialBanner'),step=state.tutorial.step||0;if(step>=5){b.hidden=true;return}const t=[['Bước 1/5','Chọn Cà rốt trong danh sách hạt giống.'],['Bước 2/5','Chạm vào ô đất trống để gieo hạt.'],['Bước 3/5','Cây vẫn lớn khi bạn đóng Farm; không cần ngồi chờ.'],['Bước 4/5','Khi cây chín, thu hoạch để đưa nông sản vào Kho.'],['Bước 5/5','Mở Chợ hoặc Đơn hàng để biến nông sản thành Vàng, EXP và vật liệu.']][step];b.hidden=false;b.innerHTML=`<div><b>${t[0]}</b><div>${t[1]}</div></div><button id="tutorialNext" class="mini-btn">Tiếp</button>`;$('#tutorialNext').onclick=()=>{state.tutorial.step++;save();renderTutorial()}}
function offlineSummary(previous){if(!previous)return;const elapsed=now()-previous;if(elapsed<30*60000)return;syncPlotHealth();ensureOrders();let ready=0,dry=0,disease=0,dead=0;for(const p of state.plots){if(!p.cropId)continue;if(p.deadAt)dead++;else{const s=careStatus(p);if(growthProgress(p)>=1)ready++;if(s.id==='dry'||s.id==='slightly')dry++;if(s.disease)disease++}}const lines=[];if(ready)lines.push(`${ready} cây đã trưởng thành.`);if(dry)lines.push(`${dry} cây đang thiếu nước.`);if(disease)lines.push(`${disease} cây có dấu hiệu bệnh.`);if(dead)lines.push(`${dead} cây đã chết.`);if(lines.length)showInfo('Trong thời gian bạn vắng mặt',`<ul class="offline-list">${lines.map(x=>`<li>${x}</li>`).join('')}</ul>${dead?'<p>Bạn có thể chạm cây chết để xem nguyên nhân, sau đó chọn “Dọn cây chết”.</p>':''}`)}
function guide(title,message,suggestions=[]){showInfo(title,`<p>${message}</p>${suggestions.length?`<b>Bạn có thể:</b><ul>${suggestions.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}`)}
function showInfo(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#infoDialog').showModal()}
function toast(msg,type=''){const t=$('#toast');t.textContent=msg;t.className=`toast ${type}`;t.hidden=false;clearTimeout(t._tm);t._tm=setTimeout(()=>t.hidden=true,2600)}
function switchTab(id){$$('.farm-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));$$('.tab-panel').forEach(p=>p.classList.toggle('active',p.id===`tab-${id}`));if(id==='villa')drawVilla()}
function ensureProfileUi(){const actions=$('.top-actions');if(actions&&!$('#profileBtn')){const b=document.createElement('button');b.id='profileBtn';b.title='Quản lý slot';b.textContent='Slot';const back=$('#backBtn');actions.insertBefore(b,back||null)}const bar=$('.statusbar');if(bar&&!$('#profileStat')){const s=document.createElement('span');s.id='profileStat';s.textContent='👨‍🌾 Chưa chọn slot';bar.prepend(s)}if(!$('#profileDialog')){const d=document.createElement('dialog');d.id='profileDialog';d.innerHTML='<div class="dialog-head"><h3>Chọn Slot Nông Trại</h3><button id="profileClose">×</button></div><div id="profileDialogBody" class="profile-dialog-body"></div><div class="dialog-actions"><button id="profileCreate" class="soft-btn">Tạo nông trại mới</button><button id="profileManageClose" class="primary-btn">Đóng</button></div>';document.body.appendChild(d)}}
function bind(){ensureProfileUi();const on=(sel,fn)=>{const el=$(sel);if(el)el.onclick=fn};on('#backBtn',()=>parent.postMessage({type:'farm-game-close'},'*'));on('#soundBtn',()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫':'♪'});on('#helpQuickBtn',()=>switchTab('help'));on('#profileBtn',()=>openProfileDialog(true));on('#profileClose',()=>$('#profileDialog')?.close());on('#profileManageClose',()=>$('#profileDialog')?.close());on('#profileCreate',()=>{const meta=getProfilesMeta();const empty=Array.from({length:PROFILE_COUNT},(_,i)=>String(i+1)).find(s=>!meta[s]);if(empty)return createProfile(empty);toast('Đã dùng hết 3 slot. Hãy dùng nút vào game ở slot muốn chơi.','warning')});on('#farmNav',e=>{const b=e.target.closest('[data-tab]');if(b)switchTab(b.dataset.tab)});$$('.action-btn').forEach(b=>b.onclick=()=>{selectedAction=b.dataset.action;setActiveAction();renderSeedButtons()});on('#waterAllBtn',waterAll);on('#expandWarehouseBtn',expandWarehouse);on('#dialogClose',()=>$('#infoDialog')?.close());on('#dialogOk',()=>$('#infoDialog')?.close());['roof','fence','path'].forEach(k=>{const el=$(`#${k}Style`);if(el)el.onchange=e=>{state.house.styles[k]=e.target.value;save();drawVilla()}})}
function startGame(){const previous=(()=>{try{return JSON.parse(localStorage.getItem(activeSaveKey())||'null')?.lastSeen||0}catch{return 0}})();load();weatherSync();syncPlotHealth();ensureOrders();renderAll();offlineSummary(previous);save();if(tickTimer)clearInterval(tickTimer);tickTimer=setInterval(()=>{syncPlotHealth();ensureOrders();renderStatus();renderFarm();renderOrders()},15000)}
function init(){bind();document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else if(gameStarted)renderAll()});window.addEventListener('beforeunload',save);ensureProfileBoot();if(!currentProfileId){openProfileDialog(true);return}gameStarted=true;startGame()}
initFarmAssets().finally(init);
